def ref(value):
    return {'$ref': value}

def call(step, name, arguments=None, **extra):
    return {'id': step, 'target': 'registry', 'name': name, 'arguments': arguments or {}, **extra}

def desktop(step, name, arguments, **extra):
    return {'id': step, 'target': 'desktop', 'name': name, 'arguments': arguments, **extra}

def action(step, target, name='', arguments=None):
    return {'id': step, 'target': target, 'name': name, 'arguments': arguments or {}}

def equal(pointer, value):
    return {'pointer': pointer, 'op': 'equal', 'value': value}

def contains(pointer, value):
    return {'pointer': pointer, 'op': 'contains', 'value': value}

def count(pointer, value):
    return {'pointer': pointer, 'op': 'length', 'value': value}

